function tickRoom(){const r=getRoom();if(!r)return;if(r.phase==="lobby"){if($("lobby").classList.contains("hidden")){showOnly("lobby");showLobbyCode(r.code||roomCode)}tickLobby();return}if(r.phase==="select"&&!$("selectScreen").classList.contains("hidden"))tickSelect();if(r.phase==="select"&&$("selectScreen").classList.contains("hidden"))showSelect();if(r.phase==="battle"&&($("hud").classList.contains("hidden")||activeBattleRound!==r.round||(!local.alive&&r.players[selfId]?.alive)))startBattle(false);if(r.phase==="upgrade"&&$("upgradeScreen").classList.contains("hidden"))showUpgrade();if(r.phase==="end"&&$("endScreen").classList.contains("hidden"))showEnd();if(r.phase==="end"&&!$("endScreen").classList.contains("hidden"))tickEnd();if(r.host===selfId)hostTick(r)}
function hostTick(r){const ids=Object.keys(r.players);if(r.phase==="select"){if(ids.every(id=>r.players[id].ready)||now()>r.deadline){ids.forEach((id,i)=>{if(!r.players[id].element)r.players[id].element=elementKeys[(Math.floor(Math.random()*elementKeys.length)+i)%elementKeys.length];r.players[id].ready=true});startRoundState(r)}}else if(r.phase==="battle"){const alive=ids.filter(id=>r.players[id].alive&&r.players[id].hp>0);let done=false;if(r.mode==="team"){const teams=[...new Set(alive.map(id=>r.players[id].team))];done=teams.length<=1}else done=alive.length<=1;if(done||now()>r.deadline){finishRound(r)}}else if(r.phase==="upgrade"){const waiting=ids.some(id=>!r.players[id].upgradeReady);if(!waiting&&r.nextStartAt&&now()>r.nextStartAt){r.round=r.pendingRound||r.round+1;r.pendingRound=0;startRoundState(r)}}else if(r.phase==="end"){const ready=r.endReady||{},allReady=ids.length>0&&ids.every(id=>ready[id]);if(allReady||(r.returnLobbyAt&&now()>r.returnLobbyAt))resetToLobby(r)}}
function resetPlayerForLobby(p){Object.assign(p,{hp:100,maxHp:100,shield:0,mana:30,maxMana:100,pos:p.pos||{x:0,y:2,z:0},rot:{x:0,y:0},alive:true,element:"",ready:false,team:0,coins:0,totalCoins:0,wins:0,kills:0,spent:0,power:1,move:1,cdMul:1,evolve:0,crowns:0,coinBonus:0,devil:false,secondaryElements:[],cooldowns:[0,0,0,0],stunUntil:0,slowUntil:0,speedUntil:0,healCutUntil:0,healCutMul:1,upgradeReady:false,rank:0});return p}
function resetToLobby(r){Object.values(r.players).forEach(resetPlayerForLobby);r.phase="lobby";r.round=1;r.deadline=0;r.pendingRound=0;r.nextStartAt=0;r.upgradeSeed=0;r.fx=[];r.endReady={};r.returnLobbyAt=0;saveRoom(r);if(r.players[selfId]){showOnly("lobby");showLobbyCode(r.code||roomCode);tickLobby()}}
function startRoundState(r){const sp=[[-38,36],[38,-36],[-36,-38],[36,38]];Object.keys(r.players).forEach((id,i)=>{const p=r.players[id],s=sp[i%sp.length];p.hp=p.maxHp;p.shield=0;p.mana=30;p.pos={x:s[0],y:2,z:s[1]};p.alive=true;p.ready=true;p.upgradeReady=false;p.rank=0;p.cooldowns=[0,0,0,0];p.hitId=p.hitId||0;p.stunUntil=0;p.slowUntil=0;p.speedUntil=0;p.healCutUntil=0;p.healCutMul=1});r.endReady={};r.returnLobbyAt=0;r.phase="battle";r.deadline=now()+90000;saveRoom(r)}
function finishRound(r){const ids=Object.keys(r.players);const ranking=ids.sort((a,b)=>{const pa=r.players[a],pb=r.players[b];if(pa.alive!==pb.alive)return pa.alive?-1:1;return pb.hp-pa.hp});const rewards=rewardTable[ids.length]||rewardTable[4];ranking.forEach((id,i)=>{const p=r.players[id],gain=(rewards[i]||1)+(p.coinBonus||0);p.coins+=gain;p.totalCoins=(p.totalCoins||0)+gain;p.rank=i+1;if(i===0)p.wins=(p.wins||0)+1});if(r.round>=r.maxRounds){r.phase="end";r.endReady={};r.returnLobbyAt=0}else{r.phase="upgrade";r.pendingRound=r.round+1;r.upgradeSeed=Math.floor(Math.random()*999999);r.nextStartAt=0;Object.values(r.players).forEach(p=>p.upgradeReady=false)}saveRoom(r)}
