function tickSelect(){const r=getRoom();if(!r)return;$("selectTimer").textContent=Math.max(0,Math.ceil((r.deadline-now())/1000));$("selectStatus").textContent=Object.values(r.players).map(p=>`${p.name}: ${p.element&&elements[p.element]?elements[p.element].name:"선택 중"}`).join(" · ")}
function showUpgrade(){showOnly("upgradeScreen");upgradePicked=false;message("upgradeStatus","");const r=getRoom(),p=r?.players?.[selfId];if(!r||!p)return;$("upgradeTitle").textContent=`${r.round}라운드 종료 보상 선택`;$("upgradeDesc").textContent=`상점은 라운드에 포함되지 않습니다. 선택 후 ${r.pendingRound||r.round+1}라운드가 시작됩니다.`;buildUpgradeOptions(p,r)}
function rng(seed){let x=Math.sin(seed)*10000;return x-Math.floor(x)}
function sample(arr,n,seed){const a=[...arr],out=[];for(let i=0;i<n&&a.length;i++){const k=Math.floor(rng(seed+i*91)*a.length);out.push(a.splice(k,1)[0])}return out}
function dedicatedCard(p,seed){const e=elements[p.element]||elements.fire,rare=rng(seed)>0.72,base=e.cards[Math.floor(rng(seed+7)*e.cards.length)];return{kind:"dedicated",title:rare?`희귀 전용 ${base.name}`:`전용 ${base.name}`,desc:rare?`${base.name} 피해와 효과가 크게 증가합니다.`:`${base.name} 성능이 증가합니다.`,apply:q=>{q.power+=rare ? .18 : .1},cost:rare?5:3}}
function buildUpgradeOptions(p,r){const common=[
{kind:"move",title:"이속증가",desc:"이동 속도 12% 증가",cost:2,apply:q=>{q.move+=.12}},
{kind:"power",title:"능력증폭",desc:"카드 피해와 회복 12% 증가",cost:3,apply:q=>{q.power+=.12}},
{kind:"hp",title:"체력증가",desc:"최대 체력 18 증가",cost:3,apply:q=>{q.maxHp+=18;q.hp=q.maxHp}},
{kind:"cool",title:"쿨타임감소",desc:"전체 카드 쿨타임 8% 감소",cost:3,apply:q=>{q.cdMul*=.92}},
{kind:"coin",title:"추가 코인 증가",desc:"매 라운드 보상 코인 +1",cost:4,apply:q=>{q.coinBonus+=1}},
{kind:"evolve",title:"진화",desc:"5번 강화하면 최종 진화 카드로 변경",cost:5,apply:q=>{q.evolve+=1;if(q.evolve>=5){q.power+=.45;q.maxHp+=35;q.hp=q.maxHp}}},
{kind:"crown",title:"왕관",desc:"7번 구매하면 악마의 카드로 변환",cost:6,apply:q=>{q.crowns+=1;if(q.crowns>=7&&!q.devil){q.devil=true;q.power+=.55;q.maxHp+=30;q.hp=q.maxHp}}},
{kind:"other",title:"랜덤 다른 능력카드",desc:"다른 원소를 보조 능력으로 흡수하고 주변 장식으로 표시",cost:4,apply:q=>{const pool=elementKeys.filter(x=>x!==q.element&&!(q.secondaryElements||[]).includes(x));const pick=pool[Math.floor(Math.random()*pool.length)]||elementKeys[0];q.secondaryElements=[...(q.secondaryElements||[]),pick].slice(-3);q.power+=.08;q.maxMana+=10}}
];
const options=sample(common,3,r.upgradeSeed+parseInt(selfId.replace(/\D/g,"").slice(0,5)||"7"));if(rng(r.upgradeSeed+99)>.58)options[Math.floor(rng(r.upgradeSeed+13)*options.length)]=dedicatedCard(p,r.upgradeSeed+23);const box=$("upgradeOptions");box.innerHTML="";options.forEach(o=>{const d=document.createElement("div");d.className="upgrade-card";d.innerHTML=`<h3>${o.title}</h3><p>${o.desc}</p><span class="tag">가격 ${o.cost}코인 · 보유 ${p.coins}코인</span>`;d.onclick=()=>pickUpgrade(o,d);box.appendChild(d)})}
function pickUpgrade(o,node){if(upgradePicked)return;const r=getRoom(),p=r?.players?.[selfId];if(!p||p.coins<o.cost){message("upgradeStatus","코인이 부족합니다.");return}o.apply(p);p.coins-=o.cost;p.spent=(p.spent||0)+o.cost;p.upgradeReady=true;r.players[selfId]=p;if(Object.values(r.players).every(x=>x.upgradeReady))r.nextStartAt=now()+3000;saveRoom(r);upgradePicked=true;document.querySelectorAll(".upgrade-card").forEach(x=>x.classList.remove("selected"));node.classList.add("selected");message("upgradeStatus","선택 완료. 모두 선택하면 3초 뒤 전투가 시작됩니다.")}
function startBattle(fresh=true){showOnly("hud");closePauseMenu();closeChat();const r=getRoom(),p=r?.players?.[selfId];if(!r||!p)return;activeBattleRound=r.round;Object.assign(local,{hp:p.hp,maxHp:p.maxHp,shield:p.shield,mana:p.mana,maxMana:p.maxMana,pos:p.pos,rot:p.rot||{x:0,y:0},element:p.element,team:p.team,coins:p.coins,totalCoins:p.totalCoins||0,spent:p.spent||0,kills:p.kills||0,power:p.power,move:p.move,cdMul:p.cdMul,evolve:p.evolve,crowns:p.crowns,devil:p.devil,secondaryElements:p.secondaryElements||[],alive:p.alive!==false&&p.hp>0,stunUntil:p.stunUntil||0,slowUntil:p.slowUntil||0,speedUntil:p.speedUntil||0,healCutUntil:p.healCutUntil||0,healCutMul:p.healCutMul||1,cooldowns:p.cooldowns||[0,0,0,0],charge:false,dashState:null,vel:{x:0,y:0,z:0}});lastHit=p.hitId||0;if(!renderer)init3d();refreshSelfVisual();refreshViewModel();lockPointer();renderCards();log(`${r.round}라운드 시작`);if(!gameLoop)animate()}
function init3d(){scene=new THREE.Scene();scene.background=new THREE.Color(0x090b10);scene.fog=new THREE.Fog(0x090b10,45,190);camera=new THREE.PerspectiveCamera(78,innerWidth/innerHeight,.1,1200);scene.add(camera);renderer=new THREE.WebGLRenderer({canvas:$("game"),antialias:true});renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setClearColor(0x090b10,1);clock=new THREE.Clock();scene.add(new THREE.HemisphereLight(0xfff5df,0x101827,1.85));const l=new THREE.DirectionalLight(0xffe5bd,1.35);l.position.set(22,34,12);scene.add(l);const fill=new THREE.PointLight(0x48cfff,.85,160);fill.position.set(0,18,0);scene.add(fill);floor=new THREE.Mesh(new THREE.PlaneGeometry(150,150,48,48),new THREE.MeshStandardMaterial({color:0x1b1720,wireframe:true,transparent:true,opacity:.28}));floor.rotation.x=-Math.PI/2;floor.position.y=-1.32;scene.add(floor);playerBody=new THREE.Object3D();scene.add(playerBody);addArena();addEvents();refreshSelfVisual();refreshViewModel()}
function addArena(){const sandMat=new THREE.MeshStandardMaterial({color:0xb68f5f,roughness:1,metalness:.02}),stoneMat=new THREE.MeshStandardMaterial({color:0x6b6259,roughness:.92,metalness:.04}),darkStone=new THREE.MeshStandardMaterial({color:0x2f2b28,roughness:.88}),wallMat=new THREE.MeshStandardMaterial({color:0x776d62,roughness:.9,side:THREE.DoubleSide});const base=new THREE.Mesh(new THREE.CylinderGeometry(arenaRadius+8,arenaRadius+8,1.2,128),stoneMat);base.position.y=-1.55;scene.add(base);const sand=new THREE.Mesh(new THREE.CircleGeometry(arenaRadius-7,128),sandMat);sand.rotation.x=-Math.PI/2;sand.position.y=-.92;scene.add(sand);const wall=new THREE.Mesh(new THREE.CylinderGeometry(arenaRadius+2,arenaRadius+2,15,128,1,true),wallMat);wall.position.y=6.2;scene.add(wall);for(let i=0;i<5;i++){const ring=new THREE.Mesh(new THREE.TorusGeometry(arenaRadius+2+i*2.15,.55,10,160),i%2?darkStone:stoneMat);ring.rotation.x=Math.PI/2;ring.position.y=1.3+i*3.05;scene.add(ring)}for(let i=0;i<80;i++){const a=i/80*Math.PI*2,x=Math.cos(a)*(arenaRadius+2.8),z=Math.sin(a)*(arenaRadius+2.8),h=11.5+(i%4)*.65;const col=new THREE.Mesh(new THREE.CylinderGeometry(.58,.82,h,14),stoneMat);col.position.set(x,h/2-1,z);col.rotation.y=-a;scene.add(col);const cap=new THREE.Mesh(new THREE.BoxGeometry(2.1,.45,1.55),darkStone);cap.position.set(x,h-1,z);cap.rotation.y=-a;scene.add(cap)}}

