function makeCapsuleBody(radius,height,material){if(THREE.CapsuleGeometry)return new THREE.Mesh(new THREE.CapsuleGeometry(radius,height,8,16),material);const g=new THREE.Group(),cyl=new THREE.Mesh(new THREE.CylinderGeometry(radius,radius,height,16),material),top=new THREE.Mesh(new THREE.SphereGeometry(radius,16,10),material),bot=new THREE.Mesh(new THREE.SphereGeometry(radius,16,10),material);top.position.y=height/2;bot.position.y=-height/2;g.add(cyl,top,bot);return g}
function addElementDetails(root,id,color,self=false){const glow=new THREE.MeshBasicMaterial({color,transparent:true,opacity:self?.46:.74});if(id==="fire"){[-.32,0,.32].forEach((x,i)=>{const f=new THREE.Mesh(new THREE.ConeGeometry(.18,.72,12),glow);f.position.set(x,1.9+.12*i,0);f.rotation.z=x*.7;root.add(f)})}else if(id==="water"){for(let i=0;i<4;i++){const b=new THREE.Mesh(new THREE.SphereGeometry(.18-i*.02,12,8),glow);const a=i*Math.PI*.5;b.position.set(Math.cos(a)*.88,.52+i*.18,Math.sin(a)*.88);root.add(b)}}else if(id==="lightning"){for(let i=0;i<4;i++){const bolt=new THREE.Mesh(new THREE.BoxGeometry(.08,.7,.08),glow);bolt.position.set((i-1.5)*.28,.85+(i%2)*.35,0);bolt.rotation.z=(i%2?.75:-.75);root.add(bolt)}}else if(id==="earth"){[-.55,.55].forEach(x=>{const s=new THREE.Mesh(new THREE.DodecahedronGeometry(.32,0),glow);s.position.set(x,.82,0);s.scale.y=.75;root.add(s)})}else if(id==="wind"){for(let i=0;i<3;i++){const r=new THREE.Mesh(new THREE.TorusGeometry(.88+i*.18,.025,8,54),glow);r.rotation.x=Math.PI/2;r.position.y=.15+i*.42;root.add(r)}}else if(id==="light"){const halo=new THREE.Mesh(new THREE.TorusGeometry(.55,.035,8,48),glow);halo.position.y=2.05;halo.rotation.x=Math.PI/2;root.add(halo)}else if(id==="darkness"){const hood=new THREE.Mesh(new THREE.TorusGeometry(.5,.08,8,32),glow);hood.position.y=1.55;hood.rotation.x=Math.PI/2;root.add(hood)}else if(id==="poison"){for(let i=0;i<6;i++){const a=i*Math.PI/3,spike=new THREE.Mesh(new THREE.ConeGeometry(.09,.48,8),glow);spike.position.set(Math.cos(a)*.72,.72,Math.sin(a)*.72);spike.rotation.z=Math.cos(a)*.8;spike.rotation.x=Math.sin(a)*.8;root.add(spike)}}}
function makeAvatar(p,self=false){const root=new THREE.Group(),id=p.element||"fire",color=elementColor(id),bodyMat=mat(id,p.devil?.65:.28);let body;if(id==="fire"){body=new THREE.Mesh(new THREE.ConeGeometry(.82,2.25,22),bodyMat);body.position.y=.08}else if(id==="water"){body=new THREE.Mesh(new THREE.SphereGeometry(.88,24,16),bodyMat);body.scale.y=1.5}else if(id==="lightning"){body=new THREE.Mesh(new THREE.OctahedronGeometry(1.02,1),bodyMat);body.scale.y=1.65}else if(id==="earth"){body=new THREE.Mesh(new THREE.DodecahedronGeometry(1.02,0),bodyMat);body.scale.y=1.42}else if(id==="wind"){body=new THREE.Mesh(new THREE.TorusKnotGeometry(.54,.19,72,10),bodyMat);body.scale.set(1.3,1.82,1.3)}else if(id==="light"){body=new THREE.Mesh(new THREE.IcosahedronGeometry(.95,1),bodyMat);body.scale.y=1.5}else if(id==="darkness"){body=makeCapsuleBody(.58,1.48,bodyMat);body.scale.y=1.16}else{body=makeCapsuleBody(.54,1.35,bodyMat);body.scale.y=1.22}root.add(body);const head=new THREE.Mesh(new THREE.SphereGeometry(.34,18,14),bodyMat);head.position.y=1.55;root.add(head);const ring=new THREE.Mesh(new THREE.TorusGeometry(1.06,.045,8,56),new THREE.MeshBasicMaterial({color,transparent:true,opacity:self?.46:.72}));ring.rotation.x=Math.PI/2;ring.position.y=-.82;root.add(ring);if(p.devil){const horns=new THREE.Group();[-.24,.24].forEach(x=>{const h=new THREE.Mesh(new THREE.ConeGeometry(.12,.45,8),new THREE.MeshBasicMaterial({color:0x210010}));h.position.set(x,1.92,0);horns.add(h)});root.add(horns)}if(p.evolve>=5){const aura=new THREE.Mesh(new THREE.TorusGeometry(1.32,.05,8,64),new THREE.MeshBasicMaterial({color:0xffffff,transparent:true,opacity:.58}));aura.rotation.x=Math.PI/2;aura.position.y=.72;root.add(aura)};(p.secondaryElements||[]).slice(0,3).forEach((sid,i)=>{const c=elementColor(sid),g=sid==="water"?new THREE.SphereGeometry(.14,10,8):sid==="fire"?new THREE.ConeGeometry(.12,.3,9):sid==="lightning"?new THREE.OctahedronGeometry(.16,0):sid==="earth"?new THREE.DodecahedronGeometry(.16,0):new THREE.SphereGeometry(.13,8,6);const o=new THREE.Mesh(g,new THREE.MeshBasicMaterial({color:c,transparent:true,opacity:self?.5:.86}));const a=i*Math.PI*2/3;o.position.set(Math.cos(a)*1.2,.68+i*.2,Math.sin(a)*1.2);o.userData.orbit={base:a,rad:1.2,speed:1.1+i*.35,h:.68+i*.2};root.add(o)});addElementDetails(root,id,color,self);root.userData.element=id;root.userData.secondary=(p.secondaryElements||[]).join(",");root.userData.devil=!!p.devil;root.userData.evolve=p.evolve||0;return root}
