function refreshViewModel(){if(!camera)return;if(viewModel)camera.remove(viewModel);const id=local.element||"fire",color=elementColor(id),m=new THREE.MeshBasicMaterial({color,transparent:true,opacity:.82}),g=new THREE.Group(),left=new THREE.Mesh(new THREE.SphereGeometry(.075,12,8),m),right=new THREE.Mesh(new THREE.SphereGeometry(.075,12,8),m),core=new THREE.Mesh(new THREE.TorusGeometry(.11,.012,8,28),m);left.position.set(-.32,-.22,-.72);right.position.set(.32,-.22,-.72);core.position.set(0,-.18,-.88);core.rotation.x=Math.PI/2;g.add(left,right,core);viewModel=g;camera.add(viewModel)}
function updateAvatar(root,dt){const t=performance.now()*.001;root.children.forEach(o=>{if(o.userData.orbit){const a=o.userData.orbit.base+t*o.userData.orbit.speed;o.position.x=Math.cos(a)*o.userData.orbit.rad;o.position.z=Math.sin(a)*o.userData.orbit.rad;o.position.y=o.userData.orbit.h+Math.sin(t*2+a)*.08}});root.rotation.y+=dt*.8}
function visualChanged(mesh,p){return mesh.userData.element!==(p.element||"fire")||mesh.userData.secondary!==(p.secondaryElements||[]).join(",")||mesh.userData.devil!==!!p.devil||mesh.userData.evolve!==(p.evolve||0)}

function addEvents(){addEventListener("resize",()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});addEventListener("keydown",e=>{if(e.target?.id==="chatInput"){if(e.code==="Escape"){e.preventDefault();closeChat()}return}if(e.code==="Escape"&&!$("hud").classList.contains("hidden")){e.preventDefault();isPauseOpen()?closePauseMenu():openPauseMenu();return}if(isPauseOpen())return;if(e.code==="Enter"&&!$("hud").classList.contains("hidden")){e.preventDefault();openChat();return}keys[e.code]=true;if(/^Digit[1-4]$/.test(e.code)){selectedCard=parseInt(e.code.at(-1))-1;renderCards()}});addEventListener("keyup",e=>{if(e.target?.id==="chatInput")return;keys[e.code]=false});addEventListener("mousemove",e=>{if(isPauseOpen()||document.pointerLockElement!==document.body)return;local.rot.y-=e.movementX*.0022;local.rot.x=clamp(local.rot.x-e.movementY*.0022,-1.35,1.35)});addEventListener("mousedown",e=>{if(e.target?.closest?.(".chat")||isPauseOpen())return;if($("hud").classList.contains("hidden"))return;if(document.pointerLockElement!==document.body)lockPointer();if(e.button===0)castCard();if(e.button===2)local.charge=true});addEventListener("mouseup",e=>{if(e.button===2)local.charge=false});addEventListener("contextmenu",e=>e.preventDefault())}
function isUltimateCard(card,index){return index===3||card?.ultimate||card?.type==="궁극기"}
function cardInfo(card){const parts=[card.damage?"피해 "+Math.round(card.damage*local.power):"보조"];if(card.heal)parts.push("회복 "+Math.round(card.heal*local.power));if(card.shield)parts.push("방어 "+Math.round(card.shield*local.power));if(card.healCut)parts.push("회복감소 "+Math.round((1-card.healCut)*100)+"%");return parts.join(" · ")}
function renderCards(){const e=elements[local.element]||elements.fire,cards=getCards(e);$("cards").innerHTML=cards.map((card,i)=>`<div class="card ${i===selectedCard?"active":""}" style="border-color:#${e.color.toString(16).padStart(6,"0")}"><h4>${card.name}</h4><p>${card.type} · 마나 ${card.mana}<br>${cardInfo(card)} · ${Math.max(.2,card.cd*local.cdMul).toFixed(1)}초</p></div>`).join("")}
function getCards(e){const arr=e.cards.map(x=>({...x}));if(arr[3])Object.assign(arr[3],{type:"궁극기",ultimate:true});if(local.evolve>=5)arr[3]={...arr[3],type:"궁극기",ultimate:true,name:"최종진화 " + arr[3].name,damage:Math.round(arr[3].damage*1.75),mana:Math.max(25,arr[3].mana-15),cd:arr[3].cd*.72,shield:(arr[3].shield||0)+25,heal:(arr[3].heal||0)+20};if(local.devil)arr.forEach((x,i)=>{x.name="악마의 "+x.name;x.damage=Math.round((x.damage||0)*1.65);x.drain=(x.drain||.25)+.35;x.mana=Math.max(10,x.mana-8);if(i===3)Object.assign(x,{type:"궁극기",ultimate:true})});return arr}
function animate(){gameLoop=requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.05);const r=getRoom();if(!r||r.phase!=="battle")return;updateLocal(dt,r);updateOpponents(r);updateEffects(dt);updateHud(r);updateNameplates(r);renderer.render(scene,camera)}
function constrainArenaPosition(pos){const d=Math.hypot(pos.x,pos.z);if(d>moveLimit){pos.x=pos.x/d*moveLimit;pos.z=pos.z/d*moveLimit}}
function healValue(v,actor=local){return Math.round(v*(now()<(actor.healCutUntil||0)?actor.healCutMul||.5:1))}
function healLocal(v){local.hp=clamp(local.hp+healValue(v),0,local.maxHp)}
function updateLocal(dt,r){if(!local.alive||isPauseOpen())return;const t=now();local.cooldowns=local.cooldowns.map(x=>Math.max(0,x-dt));if(local.charge)local.mana=clamp(local.mana+38*dt,0,local.maxMana);else local.mana=clamp(local.mana+10*dt,0,local.maxMana);const stunned=t<local.stunUntil,base=(t<local.speedUntil?9:6.5)*local.move*(t<local.slowUntil?.55:1);let forward=0,strafe=0;if(!stunned&&!local.dashState){if(keys.KeyW)forward+=1;if(keys.KeyS)forward-=1;if(keys.KeyA)strafe-=1;if(keys.KeyD)strafe+=1}const len=Math.hypot(forward,strafe)||1,sy=Math.sin(local.rot.y),cy=Math.cos(local.rot.y),fx=-sy,fz=-cy,rx=cy,rz=-sy;local.vel.x=(fx*forward/len+rx*strafe/len)*base;local.vel.z=(fz*forward/len+rz*strafe/len)*base;if(keys.ShiftLeft&&!stunned){dash();keys.ShiftLeft=false}if(keys.Space&&local.pos.y<=2.02&&!stunned&&!local.dashState){jump();keys.Space=false}const dashing=updateDash(dt,t);local.vel.y-=20*dt;if(!dashing){local.pos.x+=local.vel.x*dt;local.pos.z+=local.vel.z*dt;constrainArenaPosition(local.pos)}local.pos.y+=local.vel.y*dt;if(local.pos.y<2){local.pos.y=2;local.vel.y=0}camera.position.set(local.pos.x,local.pos.y,local.pos.z);if(selfVisual){if(visualChanged(selfVisual,local)){refreshSelfVisual();refreshViewModel()}selfVisual.position.set(local.pos.x,local.pos.y-1.55,local.pos.z);selfVisual.rotation.y=local.rot.y;updateAvatar(selfVisual,dt)}if(viewModel){viewModel.userData.kick=Math.max(0,(viewModel.userData.kick||0)-dt*1.8);viewModel.userData.pulse=Math.max(0,(viewModel.userData.pulse||0)-dt*2.4);viewModel.position.z=-(viewModel.userData.kick||0);viewModel.rotation.x=-(viewModel.userData.kick||0)*1.6;viewModel.rotation.z=Math.sin(performance.now()*.004)*.08+(viewModel.userData.pulse||0)}camera.rotation.order="YXZ";camera.rotation.y=local.rot.y;camera.rotation.x=local.rot.x;if(t-lastSync>90){patch({hp:local.hp,maxHp:local.maxHp,shield:local.shield,mana:Math.round(local.mana),pos:local.pos,rot:local.rot,alive:local.alive,cooldowns:[...(local.cooldowns||[0,0,0,0])],stunUntil:local.stunUntil||0,slowUntil:local.slowUntil||0,speedUntil:local.speedUntil||0,healCutUntil:local.healCutUntil||0,healCutMul:local.healCutMul||1,coins:local.coins,totalCoins:local.totalCoins||0,spent:local.spent||0,kills:local.kills||0,power:local.power,move:local.move,cdMul:local.cdMul,evolve:local.evolve,crowns:local.crowns,devil:local.devil,secondaryElements:local.secondaryElements||[]});lastSync=t}}
function dashConfig(id){return id==="lightning"?{dist:13,dur:.075,step:12}:id==="wind"?{dist:14,dur:.16,step:18}:id==="earth"?{dist:8,dur:.2,step:28}:id==="water"?{dist:10,dur:.22,step:24}:id==="light"?{dist:11,dur:.13,step:16}:id==="darkness"?{dist:11,dur:.14,step:18}:id==="poison"?{dist:10,dur:.2,step:24}:{dist:10,dur:.18,step:20}}
function dash(){if(local.dashState)return;const e=elements[local.element]||elements.fire,sy=Math.sin(local.rot.y),cy=Math.cos(local.rot.y),cfg=dashConfig(local.element),dir={x:-sy,z:-cy},from={x:local.pos.x,y:local.pos.y,z:local.pos.z},to={x:from.x+dir.x*cfg.dist,y:from.y,z:from.z+dir.z*cfg.dist};constrainArenaPosition(to);local.dashState={id:local.element||"fire",color:e.color,from,to,dir,t:0,dur:cfg.dur,step:cfg.step,lastTrail:0,prev:{...from}};local.vel.x=0;local.vel.z=0;dashTrail(local.dashState,true);log(e.dash)}
