function jump(){const e=elements[local.element]||elements.fire;local.vel.y=local.element==="wind"?11:local.element==="earth"?7.5:9;if(local.element==="light")healLocal(3);log(e.jump)}
function castCard(){const e=elements[local.element]||elements.fire,cards=getCards(e),card=cards[selectedCard],cd=local.cooldowns[selectedCard]||0;if(!card||cd>0||local.mana<card.mana||now()<local.stunUntil)return;local.mana-=card.mana;local.cooldowns[selectedCard]=Math.max(.2,card.cd*local.cdMul);let target=findTarget(card);if(card.shield)local.shield+=Math.round(card.shield*local.power);if(card.heal)healLocal(Math.round(card.heal*local.power));if(card.speed)local.speedUntil=now()+card.speed*1000;if(target&&card.damage>0)hitTarget(target,card,e);patch({hp:local.hp,shield:local.shield,mana:Math.round(local.mana),cooldowns:[...(local.cooldowns||[0,0,0,0])],speedUntil:local.speedUntil||0,coins:local.coins,totalCoins:local.totalCoins||0,kills:local.kills||0});skillEffect(card,target,e);recordSkillFx(card,target);useCastMotion(card);renderCards();log(card.name+" 사용")}
function findTarget(card=null){const r=getRoom();if(!r)return null;const range=isUltimateCard(card)?arenaRadius*2+32:82;let best=null,bd=999;Object.entries(r.players).forEach(([id,p])=>{if(id===selfId||!p.alive||p.hp<=0)return;if(r.mode==="team"&&p.team===local.team)return;const d=Math.hypot(p.pos.x-local.pos.x,p.pos.z-local.pos.z);if(d<bd&&d<range){bd=d;best={id,p,d}}});return best}
