function skillEndpoint(target,caster=local){const rot=caster.rot||{y:0};return target?{x:target.p.pos.x,y:target.p.pos.y+.25,z:target.p.pos.z}:{x:caster.pos.x-Math.sin(rot.y)*10,y:caster.pos.y-.2,z:caster.pos.z-Math.cos(rot.y)*10}}
function recordSkillFx(card,target){const r=getRoom();if(!r)return;const origin={x:local.pos.x,y:local.pos.y-.35,z:local.pos.z},hit=skillEndpoint(target,local);const fx={id:selfId+"-"+now()+"-"+Math.random().toString(36).slice(2,7),from:selfId,element:local.element||"fire",card:{...card},origin,hit,rot:{...local.rot},t:now()};r.fx=[...(r.fx||[]),fx].slice(-40);saveRoom(r)}
function renderRemoteFx(r){(r.fx||[]).forEach(fx=>{if(!fx?.id||lastFxSeen[fx.id])return;lastFxSeen[fx.id]=now();if(fx.from===selfId||now()-(fx.t||0)>5000||!fx.origin||!fx.hit)return;const e=elements[fx.element]||elements.fire;skillEffect(fx.card||e.cards[0],null,e,{pos:{x:fx.origin.x,y:fx.origin.y+.35,z:fx.origin.z},rot:fx.rot||{x:0,y:0},element:fx.element},fx.hit)});Object.keys(lastFxSeen).forEach(id=>{if(now()-lastFxSeen[id]>15000)delete lastFxSeen[id]})}
function skillEffect(card,target,e,caster=local,forcedHit=null){const id=caster.element||"fire",color=e.color,ultimate=isUltimateCard(card),origin={x:caster.pos.x,y:caster.pos.y-.35,z:caster.pos.z},hit=forcedHit||skillEndpoint(target,caster),size=ultimate?1.8:1;if(card.damage>0&&id!=="lightning")effectMesh(cylinderBetween(origin,hit,color,ultimate?.2:.09),ultimate?.85:.5,1.15);if(id==="fire"){const flame=new THREE.Mesh(new THREE.ConeGeometry(.8*size,2.1*size,18),effectMaterial(color,.78));flame.rotation.x=Math.PI;addEffect(flame,{x:hit.x,y:hit.y+.2,z:hit.z},.75,1.9);burstShape(hit,color,ultimate?34:18,"flame",2.1*size)}else if(id==="water"){const splash=new THREE.Mesh(new THREE.SphereGeometry(1.05*size,22,14),effectMaterial(color,.38));addEffect(splash,hit,.8,2.2);for(let i=0;i<3;i++){const wave=new THREE.Mesh(new THREE.TorusGeometry((1+i*.45)*size,.045,8,58),effectMaterial(color,.72));wave.rotation.x=Math.PI/2;addEffect(wave,{x:hit.x,y:hit.y-.85+i*.12,z:hit.z},.8,2.6)}burstShape(hit,color,ultimate?36:20,"bubble",2.3*size)}else if(id==="lightning"){for(let i=0;i<(ultimate?5:3);i++){const mid={x:(origin.x+hit.x)/2+(Math.random()-.5)*1.9,y:(origin.y+hit.y)/2+(Math.random()-.5)*1.2,z:(origin.z+hit.z)/2+(Math.random()-.5)*1.9};effectMesh(cylinderBetween(origin,mid,color,.045*size),.34,1.05);effectMesh(cylinderBetween(mid,hit,color,.045*size),.34,1.05)}burstShape(hit,color,ultimate?42:24,"bolt",1.8*size)}else if(id==="earth"){const crack=new THREE.Mesh(new THREE.TorusGeometry(1.45*size,.08,7,46),effectMaterial(0x8a5a32,.82));crack.scale.y=.38;crack.rotation.x=Math.PI/2;addEffect(crack,{x:hit.x,y:hit.y-1,z:hit.z},.95,2.35);burstShape(hit,0x9b7352,ultimate?38:22,"rock",2.5*size)}else if(id==="wind"){for(let i=0;i<5;i++){const swirl=new THREE.Mesh(new THREE.TorusGeometry((.55+i*.25)*size,.035,8,64),effectMaterial(color,.62));swirl.rotation.x=Math.PI/2+i*.22;swirl.rotation.z=i*.5;addEffect(swirl,{x:hit.x,y:hit.y-1+i*.32,z:hit.z},.75,1.7)}burstShape(hit,color,ultimate?30:16,"spark",2.5*size)}else if(id==="light"){effectMesh(cylinderBetween(origin,hit,0xfff5b6,ultimate?.24:.12),ultimate?.75:.45,1.08);for(let i=0;i<2;i++){const halo=new THREE.Mesh(new THREE.TorusGeometry((1+i*.55)*size,.04,8,72),effectMaterial(0xfff5b6,.76));halo.rotation.x=Math.PI/2;addEffect(halo,{x:hit.x,y:hit.y-.55+i*.22,z:hit.z},.85,2.2)}burstShape(hit,0xfff5b6,ultimate?32:16,"spark",1.8*size)}else if(id==="darkness"){const orb=new THREE.Mesh(new THREE.SphereGeometry(1.15*size,24,16),effectMaterial(color,.45));addEffect(orb,hit,.9,2.45);const voidRing=new THREE.Mesh(new THREE.TorusKnotGeometry(.8*size,.09,72,8),effectMaterial(0x14001f,.82));addEffect(voidRing,{x:hit.x,y:hit.y-.1,z:hit.z},.8,1.8);burstShape(hit,color,ultimate?30:17,"spark",2.1*size)}else{const cloud=new THREE.Mesh(new THREE.SphereGeometry(1.25*size,18,12),effectMaterial(color,.32));cloud.scale.y=.62;addEffect(cloud,hit,.95,2.1);burstShape(hit,color,ultimate?40:22,"bubble",2.8*size)}if(card.shield||card.heal){const aura=new THREE.Mesh(new THREE.TorusGeometry(1.2,.075,8,54),effectMaterial(card.heal?0xfff5b6:color,.78));aura.rotation.x=Math.PI/2;aura.position.set(caster.pos.x,caster.pos.y-1.05,caster.pos.z);effectMesh(aura,.85,2.8)}if(card.stun||card.slow){const snare=new THREE.Mesh(new THREE.TorusGeometry(1.1,.05,8,48),effectMaterial(card.stun?0xffffff:color,.85));snare.rotation.x=Math.PI/2;snare.position.set(hit.x,hit.y+.35,hit.z);effectMesh(snare,.75,1.8)}}
function strikeBeam(a,b,color,rad=.1,life=.55,grow=1.15){effectMesh(cylinderBetween(a,b,color,rad),life,grow)}
function ringAt(pos,color,scale=1,life=.75){const ring=new THREE.Mesh(new THREE.TorusGeometry(scale,.055,8,72),effectMaterial(color,.78));ring.rotation.x=Math.PI/2;addEffect(ring,{x:pos.x,y:pos.y-1,z:pos.z},life,2.1);return ring}
function skillEffect(card,target,e,caster=local,forcedHit=null){
const id=caster.element||"fire",color=e.color,ultimate=isUltimateCard(card),origin={x:caster.pos.x,y:caster.pos.y-.35,z:caster.pos.z},hit=forcedHit||skillEndpoint(target,caster),size=ultimate?1.9:1,above={x:hit.x,y:hit.y+12*size,z:hit.z};
if(id==="fire"){
  strikeBeam(origin,hit,color,ultimate?.2:.09,ultimate?.8:.45);
  for(let i=0;i<(ultimate?5:2);i++){const a=i/(ultimate?5:2)*Math.PI*2,p={x:hit.x+Math.cos(a)*(.55+i*.18),y:hit.y-.75,z:hit.z+Math.sin(a)*(.55+i*.18)},f=new THREE.Mesh(new THREE.ConeGeometry(.32*size,1.4*size,14),effectMaterial(color,.8));f.rotation.x=Math.PI;addEffect(f,p,.75,1.9)}
  ringAt(hit,0xff8a2f,1.05*size,.75);burstShape(hit,color,ultimate?44:22,"flame",2.2*size)
}else if(id==="water"){
  strikeBeam({x:hit.x,y:hit.y+8*size,z:hit.z},hit,color,.18*size,.72,1.05);
  for(let i=0;i<4;i++){const wave=new THREE.Mesh(new THREE.TorusGeometry((.8+i*.45)*size,.04,8,72),effectMaterial(color,.68));wave.rotation.x=Math.PI/2;addEffect(wave,{x:hit.x,y:hit.y-.85+i*.08,z:hit.z},.9,2.4)}
  const splash=new THREE.Mesh(new THREE.SphereGeometry(.75*size,20,12),effectMaterial(color,.34));splash.scale.y=1.35;addEffect(splash,hit,.8,2.2);burstShape(hit,color,ultimate?46:24,"bubble",2.4*size)
}else if(id==="lightning"){
  for(let i=0;i<(ultimate?7:4);i++){const start={x:above.x+(Math.random()-.5)*2.4*size,y:above.y+i*.45,z:above.z+(Math.random()-.5)*2.4*size},mid={x:hit.x+(Math.random()-.5)*1.6*size,y:hit.y+5*size,z:hit.z+(Math.random()-.5)*1.6*size};strikeBeam(start,mid,0xfff36a,.055*size,.32,1.02);strikeBeam(mid,hit,0xffffff,.045*size,.32,1.02)}
  ringAt(hit,0xfff36a,1.25*size,.55);burstShape(hit,0xfff36a,ultimate?52:28,"bolt",1.9*size)
}else if(id==="earth"){
  ringAt(hit,0x8a5a32,1.35*size,.95);
  for(let i=0;i<(ultimate?8:4);i++){const a=i/(ultimate?8:4)*Math.PI*2,p={x:hit.x+Math.cos(a)*(1+i*.08)*size,y:hit.y-1,z:hit.z+Math.sin(a)*(1+i*.08)*size},rock=new THREE.Mesh(new THREE.DodecahedronGeometry(.28*size,0),effectMaterial(0x9b7352,.86));rock.scale.y=1.6;addEffect(rock,p,.95,1.55)}
  burstShape(hit,0x9b7352,ultimate?44:24,"rock",2.6*size)
}else if(id==="wind"){
  strikeBeam(origin,hit,color,.06*size,.45,1.1);
  for(let i=0;i<(ultimate?8:5);i++){const swirl=new THREE.Mesh(new THREE.TorusGeometry((.45+i*.22)*size,.033,8,72),effectMaterial(color,.62));swirl.rotation.x=Math.PI/2+i*.25;swirl.rotation.z=i*.65;addEffect(swirl,{x:hit.x,y:hit.y-1+i*.28,z:hit.z},.75,1.75)}
  burstShape(hit,color,ultimate?36:18,"spark",2.6*size)
}else if(id==="light"){
  strikeBeam(above,hit,0xfff5b6,ultimate?.28:.14,ultimate?.8:.52,1.04);
  for(let i=0;i<3;i++){const halo=new THREE.Mesh(new THREE.TorusGeometry((.75+i*.48)*size,.04,8,80),effectMaterial(0xfff5b6,.76));halo.rotation.x=Math.PI/2;addEffect(halo,{x:hit.x,y:hit.y-.55+i*.2,z:hit.z},.85,2.05)}
  burstShape(hit,0xfff5b6,ultimate?38:18,"spark",2*size)
}else if(id==="darkness"){
  const orb=new THREE.Mesh(new THREE.SphereGeometry(1.05*size,28,18),effectMaterial(color,.45));addEffect(orb,hit,1,2.55);
  for(let i=0;i<2;i++){const voidRing=new THREE.Mesh(new THREE.TorusKnotGeometry((.65+i*.25)*size,.08,80,8),effectMaterial(i?color:0x14001f,.82));addEffect(voidRing,{x:hit.x,y:hit.y-.1+i*.12,z:hit.z},.85,1.75)}
  strikeBeam(origin,hit,0x2b053f,.12*size,.52,1.08);burstShape(hit,color,ultimate?38:20,"spark",2.2*size)
}else{
  const cloud=new THREE.Mesh(new THREE.SphereGeometry(1.35*size,20,12),effectMaterial(color,.32));cloud.scale.y=.62;addEffect(cloud,hit,1,2.25);
  for(let i=0;i<3;i++){const puff=new THREE.Mesh(new THREE.SphereGeometry((.45+i*.18)*size,14,10),effectMaterial(color,.26));addEffect(puff,{x:hit.x+(i-1)*.55,y:hit.y-.55+i*.1,z:hit.z+(Math.random()-.5)*.8},1,2.35)}
  burstShape(hit,color,ultimate?48:24,"bubble",3*size)
}
if(card.shield||card.heal){const aura=new THREE.Mesh(new THREE.TorusGeometry(1.2*size,.075,8,54),effectMaterial(card.heal?0xfff5b6:color,.78));aura.rotation.x=Math.PI/2;aura.position.set(caster.pos.x,caster.pos.y-1.05,caster.pos.z);effectMesh(aura,.85,2.8)}
if(card.stun||card.slow){const snare=new THREE.Mesh(new THREE.TorusGeometry(1.1*size,.05,8,48),effectMaterial(card.stun?0xffffff:color,.85));snare.rotation.x=Math.PI/2;snare.position.set(hit.x,hit.y+.35,hit.z);effectMesh(snare,.75,1.8)}
}
function useCastMotion(card){if(!viewModel)return;const ultimate=isUltimateCard(card);viewModel.userData.kick=ultimate ? .32 : .18;viewModel.userData.pulse=ultimate ? .4 : .22}
function updateEffects(dt){for(let i=effects.length-1;i>=0;i--){const e=effects[i];if(!e.max)e.max=e.life||.1;e.life-=dt;if(e.mesh.userData.v)e.mesh.position.addScaledVector(e.mesh.userData.v,dt);e.mesh.scale.multiplyScalar(1+dt*(e.mesh.userData.grow||3));if(e.mesh.material)e.mesh.material.opacity=Math.max(0,e.life/e.max);if(e.life<=0){scene.remove(e.mesh);effects.splice(i,1)}}}
function spawn(pos,color,count){if(!scene)return;for(let i=0;i<count;i++){const m=new THREE.Mesh(new THREE.SphereGeometry(.08,6,6),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.9}));m.position.set(pos.x+(Math.random()-.5)*1.5,pos.y-1+Math.random()*1.5,pos.z+(Math.random()-.5)*1.5);m.userData.v=new THREE.Vector3((Math.random()-.5)*5,Math.random()*3,(Math.random()-.5)*5);const life=.5+Math.random()*.4;scene.add(m);effects.push({mesh:m,life,max:life})}}
function updateHud(r){const roundLabel=`ROUND ${r.round} / ${r.maxRounds}`;$("hpText").textContent=Math.round(local.hp)+(local.shield?" +"+Math.round(local.shield):"");$("manaText").textContent=Math.round(local.mana);$("roundText").textContent=`${r.round} / ${r.maxRounds}`;$("roundCenter").textContent=roundLabel;$("hpBar").style.width=clamp(local.hp/local.maxHp*100,0,100)+"%";$("manaBar").style.width=clamp(local.mana/local.maxMana*100,0,100)+"%";$("roundBar").style.width=clamp(r.round/r.maxRounds*100,0,100)+"%";$("scoreboard").innerHTML=Object.values(r.players).sort(scoreSort).map(p=>`<div class="score-line"><span>${esc(p.name)}${p.team?" · T"+p.team:""}${p.devil?" · 악마":""}${p.evolve>=5?" · 최종진화":""}</span><b>${p.hp>0?Math.round(p.hp):"탈락"} HP · ${p.coins||0}C</b></div>`).join("");renderChat(r)}
function scoreSort(a,b){return (b.wins||0)-(a.wins||0)||(b.totalCoins||0)-(a.totalCoins||0)||(b.coins||0)-(a.coins||0)}
function showEnd(){showOnly("endScreen");const r=getRoom();if(!r)return;$("endTitle").textContent="최종 결과";$("finalScores").innerHTML=Object.values(r.players).sort(scoreSort).slice(0,4).map((p,i)=>`<div class="final-row rank-${i+1}"><span><strong>${i+1}위</strong>${esc(p.name)}${p.team?" · 팀 "+p.team:""}</span><b>얻은 코인 ${p.totalCoins||0} · 승리 ${p.wins||0}승 · 쓴돈 ${p.spent||0}</b></div>`).join("");tickEnd()}
function tickEnd(){const r=getRoom();if(!r)return;const ids=Object.keys(r.players),ready=r.endReady||{},count=ids.filter(id=>ready[id]).length,left=r.returnLobbyAt?Math.max(0,Math.ceil((r.returnLobbyAt-now())/1000)):0,meReady=!!ready[selfId];$("endContinue").disabled=meReady;$("endContinue").textContent=meReady?"대기 중":"넘어가기";$("endStatus").textContent=r.returnLobbyAt?`${count}/${ids.length}명 선택 · ${left}초 뒤 대기실로 이동`:`${count}/${ids.length}명 선택 · 모두 누르면 바로 이동`;}
function endContinue(){const r=getRoom();if(!r||r.phase!=="end")return;r.endReady={...(r.endReady||{}),[selfId]:true};if(!r.returnLobbyAt)r.returnLobbyAt=now()+10000;if(Object.keys(r.players).every(id=>r.endReady[id]))resetToLobby(r);else saveRoom(r);tickEnd()}
addEventListener("beforeunload",()=>{if(leavingRoom)return;persistRoomSession();const r=snapshotLocalPlayer();if(r&&networkRole==="client")sendConn(clientConn,{type:"roomUpdate",playerId:selfId,room:r});if(r&&networkRole!=="client"){const s=readStore();s[r.code]=r;writeStore(s)}try{peer?.destroy?.()}catch{}});
resumeSavedRoom();
